 4	public final class RadixSort {
 5	    private static final int RADIX = 10;
 6	
 7	    private RadixSort() {
 8	    }
 9	
10	    public static void sort(int[] values) {
11	        validateInput(values);
12	        sortValidated(values);
13	    }
14	
15	    public static int[] sortedCopy(int[] values) {
16	        validateInput(values);
17	        int[] copy = Arrays.copyOf(values, values.length);
18	        sortValidated(copy);
19	        return copy;
20	    }
21	
22	    private static void sortValidated(int[] values) {
23	        if (values.length < 2) {
24	            return;
25	        }
26	
27	        int[] output = new int[values.length];
28	        int[] counts = new int[RADIX];
29	        int maxValue = findMax(values);
30	
31	        for (int exponent = 1; maxValue / exponent > 0; exponent *= RADIX) {
32	            countingSortByDigit(values, output, counts, exponent);
33	        }
34	    }
