36	    private static void validateInput(int[] values) {
37	        Objects.requireNonNull(values, "values");
38	
39	        for (int value : values) {
40	            if (value < 0) {
41	                throw new IllegalArgumentException(
42	                    "Radix sort only supports non-negative integers."
43	                );
44	            }
45	        }
46	    }
47	
48	    private static int findMax(int[] values) {
49	        int maxValue = values[0];
50	        for (int index = 1; index < values.length; index++) {
51	            if (values[index] > maxValue) {
52	                maxValue = values[index];
53	            }
54	        }
55	        return maxValue;
56	    }
