58	    private static void countingSortByDigit(
59	        int[] values,
60	        int[] output,
61	        int[] counts,
62	        int exponent
63	    ) {
64	        Arrays.fill(counts, 0);
65	
66	        for (int value : values) {
67	            counts[digitAt(value, exponent)]++;
68	        }
69	
70	        for (int digit = 1; digit < RADIX; digit++) {
71	            counts[digit] += counts[digit - 1];
72	        }
73	
74	        for (int index = values.length - 1; index >= 0; index--) {
75	            int value = values[index];
76	            int digit = digitAt(value, exponent);
77	            output[--counts[digit]] = value;
78	        }
79	
80	        System.arraycopy(output, 0, values, 0, values.length);
81	    }
